import java.util.*;

class AuctionSystem {
    private static class Bid {
        int userId;
        int amount;

        Bid(int userId, int amount) {
            this.userId = userId;
            this.amount = amount;
        }
    }

    private static class ItemState {
        // userId -> current amount: the source of truth
        HashMap<Integer, Integer> userToAmount = new HashMap<>();
        // ordered by amount desc, then userId desc, so first() is the answer
        TreeSet<Bid> bids = new TreeSet<>((a, b) -> {
            if (a.amount != b.amount) return Integer.compare(b.amount, a.amount);
            return Integer.compare(b.userId, a.userId);
        });
    }

    private final HashMap<Integer, ItemState> items;

    public AuctionSystem() {
        items = new HashMap<>();
    }

    public void addBid(int userId, int itemId, int bidAmount) {
        ItemState state = items.computeIfAbsent(itemId, k -> new ItemState());
        // eager delete of the old entry: the comparator finds it by (amount, userId)
        Integer oldAmount = state.userToAmount.get(userId);
        if (oldAmount != null) {
            state.bids.remove(new Bid(userId, oldAmount));
        }
        state.userToAmount.put(userId, bidAmount);
        state.bids.add(new Bid(userId, bidAmount));
    }

    public void updateBid(int userId, int itemId, int newAmount) {
        ItemState state = items.get(itemId);
        int oldAmount = state.userToAmount.get(userId);
        state.bids.remove(new Bid(userId, oldAmount));
        state.userToAmount.put(userId, newAmount);
        state.bids.add(new Bid(userId, newAmount));
    }

    public void removeBid(int userId, int itemId) {
        ItemState state = items.get(itemId);
        int oldAmount = state.userToAmount.remove(userId);
        state.bids.remove(new Bid(userId, oldAmount));
        if (state.bids.isEmpty()) {
            items.remove(itemId);
        }
    }

    public int getHighestBidder(int itemId) {
        // no lazy cleanup needed: the set holds exactly the live bids
        ItemState state = items.get(itemId);
        if (state == null || state.bids.isEmpty()) return -1;
        return state.bids.first().userId;
    }
}

