#include <unordered_map>
#include <set>

class AuctionSystem {
private:
    // itemId -> (userId -> amount): the source of truth
    std::unordered_map<int, std::unordered_map<int, int>> userBids;
    // itemId -> ordered set of (amount, userId); the largest pair is the answer
    std::unordered_map<int, std::set<std::pair<int, int>>> bidSets;

public:
    AuctionSystem() {
    }

    void addBid(int userId, int itemId, int bidAmount) {
        auto& userMap = userBids[itemId];
        auto& bSet = bidSets[itemId];

        // eager delete of the old (amount, userId) pair if this user already bid
        auto it = userMap.find(userId);
        if (it != userMap.end()) {
            bSet.erase({it->second, userId});
        }
        userMap[userId] = bidAmount;
        bSet.insert({bidAmount, userId});
    }

    void updateBid(int userId, int itemId, int newAmount) {
        auto& userMap = userBids[itemId];
        auto& bSet = bidSets[itemId];

        int oldAmount = userMap[userId];
        bSet.erase({oldAmount, userId});
        bSet.insert({newAmount, userId});
        userMap[userId] = newAmount;
    }

    void removeBid(int userId, int itemId) {
        auto& userMap = userBids[itemId];
        auto& bSet = bidSets[itemId];

        int oldAmount = userMap[userId];
        bSet.erase({oldAmount, userId});
        userMap.erase(userId);

        if (userMap.empty()) {
            userBids.erase(itemId);
            bidSets.erase(itemId);
        }
    }

    int getHighestBidder(int itemId) {
        auto it = bidSets.find(itemId);
        if (it == bidSets.end() || it->second.empty()) {
            return -1;
        }
        // rbegin() is the max pair; ties fall to the larger userId automatically
        return it->second.rbegin()->second;
    }
};

