var AuctionSystem = function() {
    this.bids = new Map(); // key: "userId,itemId", value: current amount (source of truth)
    this.heaps = new Map(); // key: itemId, value: max-heap array of [amount, userId], may hold stale entries
};

const compare = (a, b) => {
    // a, b are [amount, userId]; larger amount wins, then larger userId
    if (a[0] !== b[0]) {
        return a[0] - b[0];
    }
    return a[1] - b[1];
};

const heapPush = (heap, val) => {
    heap.push(val);
    let i = heap.length - 1;
    while (i > 0) {
        const parent = Math.floor((i - 1) / 2);
        if (compare(heap[i], heap[parent]) > 0) {
            [heap[i], heap[parent]] = [heap[parent], heap[i]];
            i = parent;
        } else {
            break;
        }
    }
};

const heapPop = (heap) => {
    if (heap.length === 0) return undefined;
    const root = heap[0];
    const last = heap.pop();
    if (heap.length === 0) return root;
    heap[0] = last;
    let i = 0;
    const n = heap.length;
    while (true) {
        const left = 2 * i + 1;
        const right = 2 * i + 2;
        let largest = i;
        if (left < n && compare(heap[left], heap[largest]) > 0) {
            largest = left;
        }
        if (right < n && compare(heap[right], heap[largest]) > 0) {
            largest = right;
        }
        if (largest !== i) {
            [heap[i], heap[largest]] = [heap[largest], heap[i]];
            i = largest;
        } else {
            break;
        }
    }
    return root;
};

AuctionSystem.prototype.addBid = function(userId, itemId, bidAmount) {
    // overwrite the map and push a fresh entry; the old heap entry goes stale
    const key = userId + ',' + itemId;
    this.bids.set(key, bidAmount);
    if (!this.heaps.has(itemId)) {
        this.heaps.set(itemId, []);
    }
    const heap = this.heaps.get(itemId);
    heapPush(heap, [bidAmount, userId]);
};

AuctionSystem.prototype.updateBid = function(userId, itemId, newAmount) {
    const key = userId + ',' + itemId;
    this.bids.set(key, newAmount);
    const heap = this.heaps.get(itemId);
    heapPush(heap, [newAmount, userId]);
};

AuctionSystem.prototype.removeBid = function(userId, itemId) {
    // map only; the heap entry is discarded on a later query
    const key = userId + ',' + itemId;
    this.bids.delete(key);
};

AuctionSystem.prototype.getHighestBidder = function(itemId) {
    if (!this.heaps.has(itemId)) {
        return -1;
    }
    const heap = this.heaps.get(itemId);
    // pop until the top's amount equals the map's current amount for that user
    while (heap.length > 0) {
        const [amount, userId] = heap[0];
        const key = userId + ',' + itemId;
        const currentAmount = this.bids.get(key);
        if (currentAmount === amount) {
            return userId;
        }
        heapPop(heap);
    }
    return -1;
};

